package asciifold

import (
	"sort"
	"strings"
)

func isWS(r rune) bool { return r == ' ' || r == '\t' || r == '\n' || r == '\r' }

func words(text string) []string {
	var out []string
	var cur []rune
	for _, r := range text {
		if isWS(r) {
			if len(cur) > 0 {
				out = append(out, string(cur))
			}
			cur = nil
		} else {
			cur = append(cur, r)
		}
	}
	if len(cur) > 0 {
		out = append(out, string(cur))
	}
	return out
}

func lowerASCII(s string) string {
	rs := []rune(s)
	for i, r := range rs {
		if r >= 'A' && r <= 'Z' {
			rs[i] = r + 32
		}
	}
	return string(rs)
}

func FoldKey(text string) string {
	return strings.Join(words(lowerASCII(text)), " ")
}

func cmpRunes(a, b string) int32 {
	x, y := []rune(a), []rune(b)
	n := len(x)
	if len(y) < n {
		n = len(y)
	}
	for i := 0; i < n; i++ {
		if x[i] != y[i] {
			if x[i] < y[i] {
				return -1
			}
			return 1
		}
	}
	switch {
	case len(x) == len(y):
		return 0
	case len(x) < len(y):
		return -1
	}
	return 1
}

func CmpKeys(a, b string) int32 { return cmpRunes(FoldKey(a), FoldKey(b)) }

func SortKeys(xs []string) []string {
	type entry struct {
		s, k string
	}
	es := make([]entry, len(xs))
	for i, s := range xs {
		es[i] = entry{s, FoldKey(s)}
	}
	sort.SliceStable(es, func(i, j int) bool { return cmpRunes(es[i].k, es[j].k) < 0 })
	out := make([]string, len(xs))
	for i, e := range es {
		out[i] = e.s
	}
	return out
}

func DedupeKeys(xs []string) []string {
	seen := map[string]bool{}
	out := []string{}
	for _, s := range xs {
		k := FoldKey(s)
		if !seen[k] {
			seen[k] = true
			out = append(out, s)
		}
	}
	return out
}

func Initials(text string) string {
	var b strings.Builder
	for _, w := range words(text) {
		r := []rune(w)[0]
		if r >= 'a' && r <= 'z' {
			r -= 32
		}
		b.WriteRune(r)
	}
	return b.String()
}

